import{_ as t,c as n,o as s,j as a,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易纂言卷十二","description":"易纂言 - 易纂言卷十二","frontmatter":{"title":"易纂言卷十二","description":"易纂言 - 易纂言卷十二"},"headers":[],"relativePath":"zh/classics/zuanyan/013.md","filePath":"zh/classics/zuanyan/013.md"}'),r={name:"zh/classics/zuanyan/013.md"};function c(o,e,i,p,d,u){return s(),n("div",null,[...e[0]||(e[0]=[a("h1",{id:"易纂言卷十二",tabindex:"-1"},[l("易纂言卷十二 "),a("a",{class:"header-anchor",href:"#易纂言卷十二","aria-label":"Permalink to “易纂言卷十二”"},"​")],-1),a("p",null,"钦定四库全书",-1),a("p",null,"元吴澄撰",-1),a("p",null,"杂卦传 杂者，错糅其次，不依文王卦序也。序卦上经三十卦，下经三十四卦。以反对而观，则上经十八卦，下经十八卦也。此篇仍其反对之偶，而不仍其先后之序，故曰「杂」。其义则以明六十四卦所主之爻也。",-1),a("p",null,"「乾」刚坤柔，「比」乐师忧，「临」「观」之义，或与或求。 六十四卦，乾坤为纯刚纯柔之卦。刚柔之画自初起，至上而极，然后见「乾」为纯刚，上「坤」为纯柔，故「乾」主上九，「坤」主上六。「乾」「坤」，六阳六阴之卦，为主；「夬」「剥」，五阳五阴之卦，五为主；「大壮」「观」，四阳四阴之卦，四为主；泰「否」，三阳三阴之卦，三为主；「临」「遁」，二阳二阴之卦，二为主；复「姤」，一阳一阴之卦，初为主。此十二卦主爻，与术家世爻同。「比」九五居上，为显比之主，故「乐」。「师」九二居下，为行师之主，故「忧」。「与」者，上与下。求者，下求上。「临」九二，二阳浸长，在上之阴不敢以势临之而与之，以俟其上进。「观」六四，四阴已盛，然不进逼犯阳，而统率三阴居下，以求观九五之中正。此一节六卦，四句一韵。 屯见而不失其居，蒙杂而著。「震」，起也；「艮」，止也。「损」、「益」，盛衰之始也。 屯、蒙，皆二阳之卦。屯九五见于上卦二阴之中而为主，其下一阳则动于坎险之内而固守，故曰「不失其居」。「蒙」九二杂于下卦二阴之中而为主，其上一阳则止于坎险之外而光明，故曰「著坎」。阳陷于阴中，一也。见者，阳在上卦之天而位显。杂者，阳在下卦之地而位幽也。「震」九四起而在上卦之下。「艮」上九止而在上卦之上。「损」自泰变，泰三往上，损其下也。泰变而损，为衰之始。「益」自否变，否四来初，益其下也。否变而益，为盛之始。或以损之后必益为盛之始，益之后必损为衰之始，非也。此一节六卦，五句二韵。 大畜，时也。无妄，灾也。萃聚而升不来也，谦轻而豫怠也。 「大畜」以「大壮」之四往上为主，二阴尊而上之，得其时也。「无妄」以遁之三来初为主，九不处三，而三受失中之灾也。「萃」以观之四往上为主，而同类之三阴聚于下。升以临之三来初为主，而同类之三阴升于上。升上为往，降下为来。不来，谓升而不降也。谦一阳居下卦之上，为谦卑之主，而不尊大，故自小而轻。「豫」一阳居上卦之下，为豫乐之主，而志满足，故自肆而怠。此一节六卦，四句一韵。 噬嗑，食也。「贲」，无色也。兑见而巽伏也。「随」，无故也。「蛊」则饬也。 食者，物在口中，必噬而合之。无色者，质而不文，必贲而饬之。否，上下不交，不能噬啮而食也。「噬嗑」以否初往五而为主，否五遂得来初，成颐口之象，而可噬嗑以食。泰上下皆纯卦，无间杂之色成文也。贲以泰上来二文刚而为主，泰二遂得往上文柔，而贲其无色之质。兑上六，一阴说而见于二阳之上。巽六四，一阴入而伏于二阳之下。随初九为主，听二阴自随，而无所作为。蛊初六，为生承乾，父体坏而有所整治。无故者，无所事也。饬者，韵有所事也。此一节六卦，五句一 剥，烂也。复，反也。晋，昼也。明夷，诛也。井通而困相遇也。 剥六五，消阳将尽，仅存一阳，阳刚坏烂之极也。复初九，当纯坤之后，一阳生于下，阳刚来反之初也。晋六五，离日当天，昼也。明夷六二，离日入地。明者，夷伤也。诛，即夷伤之义。升九五，自初升五，坎水上通而将出井口。困九二，自上降二，与二阴相遇而揜其前后。此一节六卦，五句二韵。 咸，速也。恒，久也。涣，离也。节，止也。解，缓也。蹇，难也。 咸九三，不上感正应而下感，近比，欲速感也。恒初六，以柔巽处卑下，妻道之可久者也。涣九二，坎水在巽风之下，为风所离散。节九五，坎水在兑泽之上，为泽所节止。解九二，坎陷在内，震则出险而动于外，内险已解缓也。蹇九五，坎险在外，艮则见险而止于内，外险方艰难也。此一节六卦，六句，二韵。 睽，外也。家人，内也。否、泰，反其类也。大壮则止，遁则退也。 睽六五在外为主，家人六二在内为主。否三四相易为「渐」，泰三四相易为归妹。渐四复反于三，就其同类之阴，则为「否」；归妹四复反于三，就其同类之阳，则为泰，故曰「反其类也」。大壮四阳进而消阴，遁二阴进而消阳。虑后阳之恃其壮，故不欲九四之进，而欲其止；虑前阳之不及遁，故不欲六二之进，而欲其退也。圣人于五阳之夬，亦不欲阳之轻进；于一阴之姤，亦惟欲阴之不往，盖同此意也。此一节六卦，五句，一韵。 大有，众也。同人，亲也。革，去故也。鼎，取新也。小过，过也。中孚，信也。 大有六五，以一阴有五阳，所有众也。同人六二以中正同，中正，其情亲也。革六二离火在内，而兑泽燥涸，盖尾闾焦釜之火，去其泽水之故者也。鼎六五离火在上，而巽木生之，盖燧改薪传之火，取其木火之新者也。小过九四主也，而为六五所过，盖阴盛能过，阳衰不及也。中孚六四主也，而为九五所信，盖阳实能感，阴虚能应也。此一节六卦六句一韵。 丰，多故也；亲寡，旅也。离上而坎下也。小畜，寡也。履，不处也。 篇内三「故」字三义。随无故，事故之故也。革去故，新故之故也。丰多故，亲故之故也。丰六二在内，为主于明盛之中，外与四相易，而情相得，初亦往尚，三亦来孚，故旧之多也。旅六五在外，为主于羁穷之中，内与三相易，而情不相亲，相亲者寡也。盖丰盛则故旧合，旅穷则亲戚离，人情然也。离六五为主，火炎而上，故上征而折上九之首。坎九五为主，水润而下，故下比而纳六四之约。小畜，一阴畜藏于五阳之间，所畜者甚寡少也。履六三履行于二阳之上，所履者刚，又不得正位，非其所安，故行去而不留处也。此一节六卦五句一韵。 需，不进也；讼，不亲也。大过，颠也。颐，养正也。既济，定也。未济，男之穷也。归妹，女之终也。渐，女归待男行也。姤，遇也，柔遇刚也。夬，决也，刚决柔也，君子道长，小人道忧也。 需九五为主，而下三阳「需」待于内，不上进乎五也。讼九二为主，而上三阳违行于外，不下亲乎二也。萃聚，升不来，需不进，讼不亲，皆言三阴三阳之于卦主，为同类而不相与也。大过上六为主，而下应九三，犹首之向下而颠也。颐上九为主，而下养五四，以上之养下为正也。既济六二主也，以阴居阴，得其定位，而上下五爻亦皆得其定位，故曰定也。未济九二主也，以阳居阴，失其正位，而同类二阳亦皆失其正位，故曰男之穷也。三阴亦不得正位，不足言也。归妹六三，为女君之娣，而归于男家。女之少者，既归则归，女之事终也。渐九三，得男位之正，而将往迎女，六四之女待其亲迎而后行也。姤初六，一阴始生于下，而遇九二之刚，有浸长消阳之势。夬九五，五阳将极于上，而夬去上六之阴。阳刚，君子之道息而将极，故曰长；阴柔，小人之道消而将尽，故曰忧也。此一节十卦十四句五韵。先生著是书几四十年，其间稿成改易者凡数四。壬戌秋书成，然未尝以示人。明年春，观生固请锓诸梓以惠学者。先生幸慨然许之，犹虑传写之或差，乃命抄写而自督视，因正其未安，明其句读，而益加详密。写未及半，适特旨遣使召入翰林，度不可辞，不数日上道。观生随侍至郡城，集同志分帙毕写。将及九江，点校才竟，若卦图象例，陆续刊行。因书之成，遂志年月于右方云。然尝闻诸先生曰：「吾于易书用功至久，下语尤精，其象例皆自得于心，亦庶乎文王、周公繋辞之意。」又曰：「吾于书有功于世，视易为犹小，吾于易有功于世为甚大。」则读是书者，其可不知先生用意深切而泛视之哉！",-1),a("p",null,"至治癸亥五月五日，观生谨志。 易纂言卷十二。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
